# InDows module: gpu-tuning  -- MANUAL, run AFTER your GPU driver is installed.
#
# This is NOT wired into autounattend.xml: on a fresh install only the basic Microsoft display driver is
# present, so the vendor registry keys don't exist yet. Install your real NVIDIA/AMD/Intel driver first,
# then run this once in an elevated PowerShell.  Risk: advanced / hardware-dependent.

$ErrorActionPreference = 'Continue'
$log = "$env:TEMP\InDows-gpu-tuning.log"
function Log([string]$m) { "{0}  {1}" -f (Get-Date -Format 'o'), $m | Add-Content -Path $log; Write-Host $m }
function RegDword([string]$p, [string]$n, [int]$v) {
    New-ItemProperty -Path $p -Name $n -Value $v -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
}

$class = 'HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}'
Log '=== gpu-tuning start ==='
Get-ChildItem $class -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
    $p = $_.PSPath
    $d = (Get-ItemProperty -Path $p -Name 'DriverDesc' -ErrorAction SilentlyContinue).DriverDesc
    if (-not $d) { return }
    if     ($d -match 'NVIDIA')      { RegDword $p 'DisableDynamicPstate' 1; Log "NVIDIA ($d): DisableDynamicPstate = 1" }
    elseif ($d -match 'AMD|Radeon')  { RegDword $p 'EnableUlps' 0;           Log "AMD ($d): EnableUlps = 0" }
    else                             { Log "skip ($d): no tweak for this vendor" }
}
Log '=== gpu-tuning done (reboot to apply) ==='

# InDows module: network-profile
# Set the active network connection(s) to the Private profile (enables LAN discovery/sharing).
# Runs at FIRST LOGON (needs a live network). Anchor: [InDows:module] first-logon-scripts

$ErrorActionPreference = 'Continue'
$log = 'C:\Windows\Temp\InDows-network-profile.log'
function Log([string]$m) { "{0}  {1}" -f (Get-Date -Format 'o'), $m | Add-Content -Path $log }

Log '=== network-profile start ==='
Get-NetConnectionProfile -ErrorAction SilentlyContinue | ForEach-Object {
    try {
        Set-NetConnectionProfile -InterfaceIndex $_.InterfaceIndex -NetworkCategory Private -ErrorAction Stop
        Log "  set Private on '$($_.Name)'"
    } catch { Log "  FAILED on '$($_.Name)': $_" }
}
Log '=== network-profile done ==='

# InDows module: optional-features
# Enables Windows optional features via DISM. Anchor: [InDows:module] specialize-scripts
# Each line below is ONE feature the InDows GUI ticks/unticks individually (a commented line is skipped).
# Most need a reboot to finish (the first boot covers that).
#
# NOTE: run STANDALONE this enables every feature listed. Through the InDows GUI you pick which ones;
# all of them start UNticked, so nothing is enabled unless you ask for it.

$features = @(
    'Microsoft-Hyper-V-All'              # Hyper-V (Pro/Enterprise only)
    'Microsoft-Windows-Subsystem-Linux'  # WSL (legacy feature; the winget 'Microsoft.WSL' app is newer)
    'VirtualMachinePlatform'             # required by WSL2 / sandboxes
    'Containers-DisposableClientVM'      # Windows Sandbox (Pro/Enterprise only)
    'NetFx3'                             # .NET Framework 3.5
)

$ErrorActionPreference = 'Continue'
$log = 'C:\Windows\Temp\InDows-optional-features.log'
function Log([string]$m) { "{0}  {1}" -f (Get-Date -Format 'o'), $m | Add-Content -Path $log }

Log '=== optional-features start ==='
if (-not $features) { Log 'no features selected (all lines commented out)'; }
foreach ($f in $features) {
    try { Enable-WindowsOptionalFeature -Online -FeatureName $f -All -NoRestart -ErrorAction Stop | Out-Null; Log "enabled $f" }
    catch { Log "failed ${f}: $_" }
}
Log '=== optional-features done ==='

# InDows module: remove-edge
# Removes Microsoft Edge (Chromium) and the legacy Internet Explorer capability.
# Runs elevated, during the "specialize" pass (before first logon) or at first logon.
#
# GEOGRAPHY (read this): Microsoft only allows the *official* Edge uninstall in the EEA
# (European Economic Area, e.g. France). There, the command below works. Outside the EEA the
# uninstall is blocked by Microsoft; this script then just logs it and leaves Edge in place
# (enabling it elsewhere needs a region workaround that this module does NOT ship).
#
# KEPT ON PURPOSE: the Edge WebView2 Runtime (many apps depend on it) is NOT removed.
# EXPECT SIDE EFFECTS: Widgets, a few Settings deep links, and the default PDF/HTML handler may change.

$ErrorActionPreference = 'Continue'
$log = 'C:\Windows\Temp\InDows-remove-edge.log'
function Log([string]$m) { "{0}  {1}" -f (Get-Date -Format 'o'), $m | Add-Content -Path $log }

Log '=== remove-edge start ==='

# --- Internet Explorer (usually already gone on Windows 11) ---
try {
    Get-WindowsCapability -Online -ErrorAction SilentlyContinue |
        Where-Object { $_.Name -like 'Browser.InternetExplorer*' -and $_.State -eq 'Installed' } |
        ForEach-Object { Log "Removing IE capability: $($_.Name)"; Remove-WindowsCapability -Online -Name $_.Name -ErrorAction SilentlyContinue | Out-Null }
} catch { Log "IE removal skipped: $_" }

# --- Microsoft Edge (Chromium): official uninstall via its own setup.exe ---
$setup = Get-ChildItem 'C:\Program Files (x86)\Microsoft\Edge\Application' -Recurse -Filter 'setup.exe' -ErrorAction SilentlyContinue |
         Where-Object { $_.FullName -match '\\Installer\\setup\.exe$' } | Select-Object -First 1
if ($setup) {
    Log "Uninstalling Edge via: $($setup.FullName)"
    & $setup.FullName '--uninstall' '--system-level' '--verbose-logging' '--force-uninstall'
    Log "Edge setup.exe exit: $LASTEXITCODE  (a non-zero code usually means the uninstall is blocked in your region)"
} else {
    Log 'Edge setup.exe not found (already removed?).'
}

# --- Stop EdgeUpdate from bringing Chromium Edge back ---
try {
    New-Item -Path 'HKLM:\SOFTWARE\Microsoft\EdgeUpdate' -Force -ErrorAction SilentlyContinue | Out-Null
    Set-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\EdgeUpdate' -Name 'DoNotUpdateToEdgeWithChromium' -Value 1 -Type DWord -ErrorAction SilentlyContinue
} catch { Log "EdgeUpdate guard skipped: $_" }

# --- Tidy leftover desktop shortcuts ---
Get-ChildItem "$env:PUBLIC\Desktop", "$env:USERPROFILE\Desktop" -Filter '*Edge*.lnk' -ErrorAction SilentlyContinue |
    Remove-Item -Force -ErrorAction SilentlyContinue

Log '=== remove-edge done ==='

# InDows module: remove-onedrive
# Uninstalls OneDrive and hides its File Explorer entry.
# Anchor: [InDows:module] first-logon-scripts

$ErrorActionPreference = 'Continue'
$log = 'C:\Windows\Temp\InDows-remove-onedrive.log'
function Log([string]$m) { "{0}  {1}" -f (Get-Date -Format 'o'), $m | Add-Content -Path $log }
function RegDword([string]$p, [string]$n, [int]$v) {
    New-Item -Path $p -Force -ErrorAction SilentlyContinue | Out-Null
    New-ItemProperty -Path $p -Name $n -Value $v -PropertyType DWord -Force -ErrorAction SilentlyContinue | Out-Null
}

Log '=== remove-onedrive start ==='
Get-Process 'OneDrive' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
$setup = "$env:SystemRoot\SysWOW64\OneDriveSetup.exe"
if (-not (Test-Path $setup)) { $setup = "$env:SystemRoot\System32\OneDriveSetup.exe" }
if (Test-Path $setup) { Start-Process -FilePath $setup -ArgumentList '/uninstall' -Wait -ErrorAction SilentlyContinue; Log "uninstalled via $setup" }
else { Log 'OneDriveSetup.exe not found.' }

# Hide the OneDrive entry from the Explorer navigation pane (both 64-bit and 32-bit views)
foreach ($k in 'HKLM:\SOFTWARE\Classes\CLSID\{018D5C66-4533-4307-9B53-224DE2ED1FE6}',
               'HKLM:\SOFTWARE\Wow6432Node\Classes\CLSID\{018D5C66-4533-4307-9B53-224DE2ED1FE6}') {
    RegDword $k 'System.IsPinnedToNameSpaceTree' 0
}
Log '=== remove-onedrive done ==='

# InDows module: scheduled-tasks
# Disables telemetry / CEIP / error-reporting scheduled tasks.
# Anchor: [InDows:module] first-logon-scripts  (the Task Scheduler service is fully up at logon)

$ErrorActionPreference = 'Continue'
$log = 'C:\Windows\Temp\InDows-scheduled-tasks.log'
function Log([string]$m) { "{0}  {1}" -f (Get-Date -Format 'o'), $m | Add-Content -Path $log }

$tasks = @(
    @{ p = '\Microsoft\Windows\Customer Experience Improvement Program\'; n = 'Consolidator' }
    @{ p = '\Microsoft\Windows\Customer Experience Improvement Program\'; n = 'UsbCeip' }
    @{ p = '\Microsoft\Windows\Application Experience\';                  n = 'Microsoft Compatibility Appraiser' }
    @{ p = '\Microsoft\Windows\Application Experience\';                  n = 'ProgramDataUpdater' }
    @{ p = '\Microsoft\Windows\Windows Error Reporting\';                 n = 'QueueReporting' }
    @{ p = '\Microsoft\Windows\Feedback\Siuf\';                           n = 'DmClient' }
    @{ p = '\Microsoft\Windows\Feedback\Siuf\';                           n = 'DmClientOnScenarioDownload' }
    @{ p = '\Microsoft\Windows\DiskDiagnostic\';                          n = 'Microsoft-Windows-DiskDiagnosticDataCollector' }
)

Log '=== scheduled-tasks start ==='
foreach ($t in $tasks) {
    try { Disable-ScheduledTask -TaskPath $t.p -TaskName $t.n -ErrorAction Stop | Out-Null; Log "disabled $($t.p)$($t.n)" }
    catch { Log "skip $($t.p)$($t.n): $_" }
}
Log '=== scheduled-tasks done ==='
